// src/service/resend-service.js
var resendService = {
  async webhooks(c2, body) {
    const params = {
      resendEmailId: body.data.email_id,
      status: emailConst.status.SENT
    };
    if (body.type === "email.delivered") {
      params.status = emailConst.status.DELIVERED;
      params.message = null;
    }
    if (body.type === "email.complained") {
      params.status = emailConst.status.COMPLAINED;
      params.message = null;
    }
    if (body.type === "email.bounced") {
      let bounce = body.data.bounce;
      bounce = JSON.stringify(bounce);
      params.status = emailConst.status.BOUNCED;
      params.message = bounce;
    }
    if (body.type === "email.delivery_delayed") {
      params.status = emailConst.status.DELAYED;
      params.message = null;
    }
    if (body.type === "email.failed") {
      params.status = emailConst.status.FAILED;
      params.message = body.data.failed.reason;
    }
    const emailRow = await email_service_default.updateEmailStatus(c2, params);
    if (!emailRow) {
      console.warn(`resend webhook: unknown email_id ${params.resendEmailId}, type ${body.type}`);
      return;
    }
  }
};
var resend_service_default = resendService;

